import{_ as t,o as r,c as i,ah as n}from"./chunks/framework.DDXs_i7t.js";const c=JSON.parse('{"title":"Unterstützen Sie das Mysterium","description":"","frontmatter":{},"headers":[],"relativePath":"unterstuetzen.md","filePath":"unterstuetzen.md"}'),a={name:"unterstuetzen.md"};function s(o,e,d,h,u,l){return r(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="unterstutzen-sie-das-mysterium" tabindex="-1">Unterstützen Sie das Mysterium <a class="header-anchor" href="#unterstutzen-sie-das-mysterium" aria-label="Permalink to &quot;Unterstützen Sie das Mysterium&quot;">​</a></h1><p><strong>Unabhängigkeit hat einen Preis. Aber sie ist nicht käuflich.</strong></p><p>„Das Horten-Mysterium“ ist ein freies, investigatives Kunstprojekt. Wir nehmen keine Großspenden von anonymen Vereinen an, wir stückeln keine Beträge unter der Meldegrenze und wir haben keine Inseraten-Deals mit dem Boulevard.</p><p>Um die laufenden Kosten für Recherche, Server und die Weiterentwicklung der KI-Modelle zu decken, sind wir auf Ihre Unterstützung angewiesen.</p><hr><h2 id="📂-das-premium-dossier-digitaler-download" tabindex="-1">📂 Das Premium-Dossier (Digitaler Download) <a class="header-anchor" href="#📂-das-premium-dossier-digitaler-download" aria-label="Permalink to &quot;📂 Das Premium-Dossier (Digitaler Download)&quot;">​</a></h2><p>Holen Sie sich das volle Paket für Ihr privates Archiv. Unser <strong>„Master-Dossier: Das System Horten-Benko“</strong> enthält das komplette Drehbuch, alle Recherchen und exklusive Medien.</p><p>👉 <strong><a href="/Premium_Dossier_Master.html">Master-Dossier Vorschau (DE)</a></strong> | <strong><a href="/en/Premium_Dossier_Master_EN.html">Master Dossier Preview (EN)</a></strong></p><p>👉 <strong>[Vollständiges Dossier kaufen via Gumroad (Platzhalter)]</strong></p><hr><h2 id="☕-die-investigative-tip-box" tabindex="-1">☕ Die investigative Tip-Box <a class="header-anchor" href="#☕-die-investigative-tip-box" aria-label="Permalink to &quot;☕ Die investigative Tip-Box&quot;">​</a></h2><p>Sie möchten kein Dossier, aber unsere Nachtschichten im Archiv mit einem Kaffee unterstützen? Jede kleine Geste hilft, die Maschine am Laufen zu halten.</p><div style="text-align:center;margin:2rem 0;"><a href="https://ko-fi.com/voltisodala" target="_blank" style="background:#29abe0;color:white;padding:15px 30px;border-radius:30px;text-decoration:none;font-weight:bold;font-size:1.2rem;display:inline-flex;align-items:center;gap:10px;box-shadow:0 5px 15px rgba(41,171,224,0.4);"><img src="https://ko-fi.com/img/cup-border.png" style="height:25px;"> Spendier uns einen Kaffee </a><p style="margin-top:10px;font-size:0.9rem;color:#666;">Sicherer Check-out via Ko-fi</p></div><hr><h2 id="👕-merch-die-asthetik-des-schweigens-bald-verfugbar" tabindex="-1">👕 Merch: Die Ästhetik des Schweigens (Bald verfügbar) <a class="header-anchor" href="#👕-merch-die-asthetik-des-schweigens-bald-verfugbar" aria-label="Permalink to &quot;👕 Merch: Die Ästhetik des Schweigens (Bald verfügbar)&quot;">​</a></h2><p>Tragen Sie die Satire auf der Haut. Von der „Sobotka-Orgel“ auf dem T-Shirt bis zur „49.000er-Tranchen“-Tasse.</p><hr><h3 id="warum-unterstutzen" tabindex="-1">Warum unterstützen? <a class="header-anchor" href="#warum-unterstutzen" aria-label="Permalink to &quot;Warum unterstützen?&quot;">​</a></h3><p>Jeder Euro fließt direkt in die Erweiterung des Projekts. Wir arbeiten aktuell an der <strong>Vertonung des Hörbuchs</strong> mit den Stimmen von Minichmayr, Diehl und Masucci (via KI). Ihre Unterstützung beschleunigt diesen Prozess massiv.</p><p><strong>Vielen Dank für Ihre Hilfe bei der Aufdeckung des Mysteriums!</strong></p>',20)])])}const g=t(a,[["render",s]]);export{c as __pageData,g as default};
